/**
 * Base64-encoded font subsets embedded into SVG <style> blocks.
 * Generated by scripts/build-fonts.ts — do not edit manually.
 */

export const JETBRAINS_MONO_BASE64 = "";
export const FRAUNCES_BASE64 = "";

export function fontDefs(): string {
  if (!JETBRAINS_MONO_BASE64) return "";
  return `
  <style>
    @font-face {
      font-family: 'JetBrains Mono';
      font-style: normal;
      font-weight: 400;
      src: url('data:font/woff2;charset=utf-8;base64,${JETBRAINS_MONO_BASE64}') format('woff2');
    }
  </style>`;
}
